import 'package:flutter/cupertino.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../../../Core/Utils/Widget/custom_scaffold_messenger.dart';import '../../data/models/update_password.dart';import '../../domain/useCase/update_password_use_case.dart';import '../../domain/useCase/update_user_use_case.dart';import '../../data/models/update_user.dart';part 'user_state.dart';class UserCubit extends Cubit<UserClassState> {  UserCubit(this.updateUserUseCase, this.updatePasswordUseCase)      : super(UserClassState());  final UpdateUserUseCase updateUserUseCase;  final UpdatePasswordUseCase updatePasswordUseCase;  Future<void> updateUser(BuildContext context, UpdateUser updateUser) async {    emit(state.copyWith(loading: true));    final result = await updateUserUseCase.call(updateUser);    result.fold(      (l) {        emit(state.copyWith(            loading: false, success: false, error: l.errMessage));        showCustomSnackBar(context, l.errMessage, SnackBarType.error);      },      (r) {        emit(state.copyWith(          loading: false,          success: true,        ));        showCustomSnackBar(context, "Update Succeed", SnackBarType.error);      },    );  }  Future<void> updatePassword(      BuildContext context, UpdatePassword updateUser) async {    emit(state.copyWith(loading: true));    final result = await updatePasswordUseCase.call(updateUser);    result.fold(      (l) {        emit(state.copyWith(            loading: false, success: false, error: l.errMessage));        showCustomSnackBar(context, l.errMessage, SnackBarType.error);      },      (r) {        emit(state.copyWith(          loading: false,          success: true,        ));        showCustomSnackBar(context, "Update Succeed", SnackBarType.error);      },    );  }  get loading => state.loading;}